def merge(intervals: list[list[int]]) -> list[list[int]]:
    intervals.sort(key=lambda x: x[0])
    res = []
    for it in intervals:
        if not res or res[-1][1] < it[0]: res.append(it)
        else: res[-1][1] = max(res[-1][1], it[1])
    return res

